using System.Net;
using System.Runtime.CompilerServices;
using System.Text.Json;
using System.Text.Json.Nodes;
using Insolvia.Api.Tests.Support;
using Insolvia.Domain.CaseEntities;

namespace Insolvia.Api.Tests.OpenApi;

/// <summary>
/// The API's OpenAPI document is generated by the server from its endpoints
/// (Hosting/ApiDocument.cs) and served at <c>/openapi/v1.json</c>;
/// <c>docs/reference/openapi/api.json</c> is a committed copy, for readers
/// and for the contract suite, which checks every exchange it makes against it.
/// These keep the copy current, and keep every route typed: a handler that
/// returns a bare <c>IResult</c> has no response schema for the document to show.
/// </summary>
public sealed class OpenApiDocumentTests : IDisposable
{
    /// <summary>Set to <c>1</c> to write the served document over the committed copy.</summary>
    public const string WriteVariable = "INSOLVIA_WRITE_OPENAPI";

    [Fact]
    public async Task The_reference_page_is_served_at_docs()
    {
        using var client = _world.Host.CreateClient();
        using var response = await client.GetAsync(new Uri("/docs", UriKind.Relative), TestContext.Current.CancellationToken);

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        Assert.Equal("text/html", response.Content.Headers.ContentType?.MediaType);
    }

    private const string Regenerate = $"Run backend/scripts/dev-openapi.sh (which sets {WriteVariable}=1 for this test) and commit docs/reference/openapi/api.json.";

    private readonly FirmWorld _world = new();

    public void Dispose() => _world.Dispose();

    [Fact]
    public async Task The_committed_document_is_the_one_the_api_serves()
    {
        var served = await ServedAsync();
        var path = CommittedPath();
        if (Environment.GetEnvironmentVariable(WriteVariable) == "1")
        {
            await File.WriteAllTextAsync(path, served.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + "\n", TestContext.Current.CancellationToken);
        }

        var committed = JsonNode.Parse(await File.ReadAllTextAsync(path, TestContext.Current.CancellationToken));
        Assert.True(JsonNode.DeepEquals(served, committed), $"docs/reference/openapi/api.json is out of date. {Regenerate}");
    }

    [Fact]
    public async Task Every_route_the_api_maps_is_in_the_document()
    {
        var operations = Operations(await ServedAsync()).Select(operation => operation.Key).ToHashSet(StringComparer.Ordinal);
        var missing = Mapped().Where(route => !operations.Contains(route)).ToList();

        Assert.True(missing.Count == 0, $"Not in the document: {string.Join(", ", missing)}.");
    }

    [Fact]
    public async Task Every_operation_documents_what_it_answers()
    {
        var untyped = Operations(await ServedAsync())
            .Where(operation => !operation.Value["responses"]!.AsObject()
                .Any(response => response.Key.StartsWith('2') && (response.Key == "204" || response.Value?["content"] is JsonObject { Count: > 0 })))
            .Select(operation => operation.Key)
            .ToList();

        Assert.True(
            untyped.Count == 0,
            $"No success response with a body: {string.Join(", ", untyped)}. Return a typed result (a record, TypedResults.Created(...), Results<...>), or declare a non-JSON body with .Produces(200, contentType: ...).");
    }

    private async Task<JsonNode> ServedAsync()
    {
        using var client = _world.Host.CreateClient();
        var text = await client.GetStringAsync(new Uri("/openapi/v1.json", UriKind.Relative), TestContext.Current.CancellationToken);
        return JsonNode.Parse(text)!;
    }

    private static IEnumerable<KeyValuePair<string, JsonNode>> Operations(JsonNode document) =>
        document["paths"]!.AsObject().SelectMany(path => path.Value!.AsObject()
            .Select(operation => KeyValuePair.Create($"{operation.Key.ToUpperInvariant()} {path.Key}", operation.Value!)));

    private List<string> Mapped() =>
        [.. _world.Host.Services.GetRequiredService<EndpointDataSource>().Endpoints
            .OfType<RouteEndpoint>()
            // FirmWorld's own probes (AuthHost), and the document itself.
            .Where(endpoint => endpoint.RoutePattern.RawText is { } raw && !raw.StartsWith("/test/", StringComparison.Ordinal) && !raw.StartsWith("/openapi/", StringComparison.Ordinal) && !raw.StartsWith("/docs", StringComparison.Ordinal))
            .SelectMany(endpoint => (endpoint.Metadata.GetMetadata<IHttpMethodMetadata>()?.HttpMethods ?? [])
                .Select(method => $"{method} {endpoint.RoutePattern.RawText}"))
            // The document gives a /{collection} route one path per collection (ApiDocument).
            .SelectMany(route => route.Contains("{collection}", StringComparison.Ordinal)
                ? CaseCollections.Kinds.Select(kind => route.Replace("{collection}", kind.Collection, StringComparison.Ordinal))
                : [route])];

    // From this source file to the repository's docs/, so the write lands in the checkout.
    private static string CommittedPath([CallerFilePath] string source = "") =>
        Path.GetFullPath(Path.Combine(Path.GetDirectoryName(source)!, "..", "..", "..", "..", "docs", "reference", "openapi", "api.json"));
}
